owner_rust_function.full_function_text:
fn test_fail_read() {
    let (_, o) = run(
        "minimal-aes256.pdf",
        None,
        &[
            "sign",
            "addfields",
            "--field",
            "1/0,0,100,100/Sig1",
            "input.pdf",
            "out.pdf",
        ],
    );
    assert_eq!(o.status.code(), Some(1));
    assert!(text(&o).contains("Failed to read"), "{}", text(&o));
}
